// YouTube không tự đăng: lượt theo lịch (21h) chỉ nhắn video kế tiếp kèm nút đăng (trang quản lý Telegram xử lý nút),
// bấm mới đăng. Video kế tiếp: format = youtube đang pending, truyện cũ trước, trong mỗi truyện các phần trước, trọn bộ sau cùng.
// Bấm đăng (ở tin nhắc hoặc màn hình một truyện) thì trang quản lý gọi workflow này kèm id: đăng đúng video đó, bỏ qua giờ hẹn.
// Tạm dừng lịch trong trang quản lý (tab CaiDat: youtube_auto = off) thì 21h không nhắc; nút đăng vẫn dùng được.
// Bấm từ Telegram mà không đăng được thì nhắn lý do.
const force = $('Đăng từ Telegram').isExecuted;
const want = force ? String($('Đăng từ Telegram').first().json.id ?? '') : '';
const rows = $('Đọc Sheet').all().map((i) => i.json);
// Tab CaiDat chưa có thì lịch coi như đang bật; đọc lỗi kiểu khác thì lượt theo lịch thôi nhắc (không biết lịch có tạm dừng không).
const errorText = (e) => (typeof e === 'string' ? e : e?.message ?? JSON.stringify(e));
const flagRows = $('Đọc cài đặt').all().map((i) => i.json);
const flagError = flagRows.map((f) => f.error).find((e) => e && !/not found|unable to parse range/i.test(errorText(e)));
let auto = true;
for (const f of flagRows) if (f.key === 'youtube_auto') auto = String(f.value) !== 'off';
if ((!auto || flagError) && !force) return [];
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Tên ngắn của truyện, như storyNameFromTitle của Story Studio: dòng đầu caption TikTok ("Tên truyện | Phần 1/5"),
// hoặc tên rút từ tiêu đề khi caption cũ còn tiêu đề dài.
const TITLE_TAGS = /\[[^\]]*\]|【[^】]*】|\([^)]*\)|#\S*|\b(cre|credit|nguồn|source)\s*:.*$|\d[\d.,]*\s*[kmb]?\s*(views?|lượt xem|reactions?|likes?|lượt thích|comments?|bình luận|shares?)/giu;
const TITLE_SEPARATORS = /\s+[-–—]\s+|\s*[|·•]\s*|[:.]\s+/u;
const TITLE_NOISE = /^(\d+|full( bộ)?|trọn bộ|\d+\s*(phút|giờ|tiếng)|(tập|phần|part|ep)\s*\d+|.*\b(audio|official|channel|radio|podcast)\b.*|truyện (ngắn|audio|ma|hay|kể|kinh dị|ngôn tình|cổ tích|trinh thám)\b.*)$/iu;
const nameFromTitle = (title) => {
  const pieces = String(title ?? '').replace(TITLE_TAGS, ' ').split(TITLE_SEPARATORS).map((s) => s.replace(/["“”'‘’]/g, '').trim()).filter(Boolean);
  return pieces.find((s) => !TITLE_NOISE.test(s)) ?? pieces.join(' ');
};
// Đuôi Story Studio thêm sau tên truyện: " | Phần 1/5", hoặc ở video cả truyện " (Truyện Full) #gactro12 | Gác trọ Audio"
// (số của truyện và tên kênh có khi có); caption cũ ghi " (trọn bộ)".
const NAME_SUFFIX = /\s*(\|\s*Phần\s*\d+\s*\/\s*\d+|\((Truyện Full|trọn bộ)\)(\s+#\S+)*(\s*\|.*)?)\s*$/iu;
const FULL_NAME = /\(Truyện Full\)/iu;
const NAME_MAX = 45;
/**
 * Tên ngắn của truyện của một dòng trong Sheet, không kèm số phần, số của truyện hay tên kênh. Dòng YouTube không lấy
 * caption (đó là mô tả YouTube) mà lấy tiêu đề video cả truyện do Story Studio đặt, hoặc rút từ tiêu đề AI viết.
 */
const shortName = (r) => {
  const title = String(r.post_title ?? '');
  const named = r.format === 'youtube' ? (FULL_NAME.test(title) ? title : '') : String(r.post_description ?? '').split('\n')[0];
  const line = named.replace(NAME_SUFFIX, '').replace(/^(#\S+\s+)+/u, '').trim();
  for (const c of [line, nameFromTitle(line), nameFromTitle(r.post_title), nameFromTitle(r.title), String(r.title ?? '').trim()]) {
    if (c && c.length <= NAME_MAX) return c;
  }
  const t = line || String(r.title || r.id || '');
  return t.length > NAME_MAX ? `${t.slice(0, NAME_MAX - 1).replace(/\s+\S*$/, '')}…` : t;
};
const mine = rows.filter((r) => r.format === 'youtube');
const rank = (r) => (r.kind === 'full' ? Infinity : Number(r.part || 0));
const order = (a, b) => String(a.job_id).localeCompare(String(b.job_id)) || rank(a) - rank(b);
const due = (r) => !r.scheduled_at || DateTime.fromISO(String(r.scheduled_at)) <= $now;
const label = (r) => String(r.post_title || r.title || r.id);
const info = (text) => (force ? [{ json: { mode: 'info', text } }] : []);
// Video đang đăng dở (khoá chưa quá 3 giờ) thì không đăng chồng, cũng không nhắc.
const sending = mine.find((r) => r.status === 'posting' && $now.diff(DateTime.fromISO(String(r.posted_at ?? '')), 'hours').hours < 3);
if (sending) return info(`⏳ Đang đăng ${label(sending)} lên YouTube, xong bot sẽ nhắn link.`);
if (want) {
  const r = mine.find((x) => String(x.id) === want);
  if (!r) return info('Không tìm thấy video YouTube này trong Sheet.');
  if (r.status !== 'pending') return info(`${label(r)} đang ở trạng thái ${r.status}, không đăng.`);
  return [{ json: { mode: 'send', row: r } }];
}
const pending = mine.filter((r) => r.status === 'pending').sort(order);
const next = pending.find(due);
if (!force) {
  if (!next) return [];
  const sec = Math.round(Number(next.duration_sec) || 0);
  const pad = (n) => String(n).padStart(2, '0');
  const length = sec >= 3600 ? `${Math.floor(sec / 3600)}:${pad(Math.floor(sec / 60) % 60)}:${pad(sec % 60)}` : `${Math.floor(sec / 60)}:${pad(sec % 60)}`;
  const privacy = { public: 'công khai', unlisted: 'không công khai', private: 'riêng tư' }[$('Cấu hình YouTube').first().json.privacy_status] ?? 'công khai';
  return [{ json: {
    mode: 'info', parse_mode: 'HTML',
    text: [
      `⏰ <b>Đến giờ đăng YouTube</b> · ${pending.length} video đang chờ`,
      '',
      `📖 ${esc(shortName(next))}${next.part ? ` · Phần ${next.part}/${next.total_parts}` : ''}`,
      `🎬 ${esc(label(next))}`,
      `⏱ ${length}`,
      '',
      `Bấm nút bên dưới để đăng (${privacy}). Không bấm thì video vẫn chờ, lượt nhắc sau sẽ nhắc lại.`,
    ].join('\n'),
    reply_markup: { inline_keyboard: [
      [{ text: '✅ Đăng lên YouTube ngay', callback_data: `st|ytpost|${next.job_id}` }],
      [{ text: '📖 Mở truyện', callback_data: `st|view|${next.job_id}` }],
    ] },
  } }];
}
if (next) return [{ json: { mode: 'send', row: next } }];
const later = pending[0];
if (later) return info(`🕒 Video YouTube tiếp theo (${label(later)}) hẹn đăng lúc ${DateTime.fromISO(String(later.scheduled_at)).setZone('Asia/Ho_Chi_Minh').toFormat('HH:mm dd/MM')}.`);
return info('📭 Hết video YouTube để đăng.');

const cfg = $('Cấu hình YouTube').first().json;
// Chưa điền bot Telegram thì bỏ qua bước nhắn tin.
if (!cfg.telegram_bot_token || cfg.telegram_bot_token.startsWith('DAN_')) return [];
// Tin nhắc đăng lúc 21h có định dạng HTML và nút đăng; tin báo khi bấm từ Telegram là chữ thường.
return [{ json: { payload: {
  chat_id: cfg.telegram_chat_id, text: $json.text,
  ...($json.parse_mode ? { parse_mode: $json.parse_mode } : {}),
  ...($json.reply_markup ? { reply_markup: $json.reply_markup } : {}),
} } }];

// Hai lượt cùng chọn một video (bấm hai lần liền, hoặc lịch chạy đúng lúc bấm): cả hai ghi khoá (posted_at) rồi đợi vài giây.
// Lượt ghi sau cùng giữ video; lượt kia thấy khoá đã khác thì dừng, không gửi trùng.
// Không đọc lại được dòng, hoặc posted_at không còn dạng ISO (Sheet tự đổi định dạng), thì không kiểm được: chạy tiếp như trước.
const me = $('Lấy 1 video').first().json;
const now = $input.all().map((i) => i.json).find((r) => String(r.id) === String(me.id));
const mine = DateTime.fromISO(String(me.lock ?? ''));
const seen = DateTime.fromISO(String(now?.posted_at ?? ''));
if (now && mine.isValid && seen.isValid && seen.toMillis() !== mine.toMillis()) return [];
return [{ json: me }];

// YouTube từ chối tiêu đề, mô tả có dấu < >, tiêu đề quá 100 ký tự, mô tả quá 5000 byte và thẻ tổng quá 500 ký tự.
const r = $('Lấy 1 video').first().json;
const clean = (s) => String(s ?? '').replace(/[<>]/g, '').trim();
const cut = (s, n) => (s.length <= n ? s : `${s.slice(0, n - 1).trimEnd()}…`);
const title = cut(clean(r.post_title) || clean(r.title) || 'Video', 100);
// Hashtag của truyện ở cuối mô tả; YouTube hiện ba cái đầu phía trên tiêu đề.
const description = cut([clean(r.post_description), clean(r.hashtags)].filter(Boolean).join('\n\n'), 4500);
const tags = [];
let room = 450;
for (const t of String(r.tags ?? '').split(',').map((x) => clean(x).replace(/"/g, '')).filter(Boolean)) {
  // Thẻ có khoảng trắng bị YouTube tính thêm hai dấu ngoặc kép, mỗi thẻ thêm một dấu phẩy.
  const cost = t.length + (t.includes(' ') ? 2 : 0) + 1;
  if (tags.includes(t) || cost > room) continue;
  tags.push(t);
  room -= cost;
}
return [{ json: { title, description, tags: tags.join(',') } }];

const cfg = $('Cấu hình YouTube').first().json;
// Chưa điền bot Telegram thì bỏ qua bước nhắn tin.
if (!cfg.telegram_bot_token || cfg.telegram_bot_token.startsWith('DAN_')) return [];
const r = $('Lấy 1 video').first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const p = $('Chuẩn bị nội dung').first().json;
const video = $('Đăng YouTube').first().json;
const id = video.id;
const sec = Math.round(Number(r.duration_sec) || 0);
const pad = (n) => String(n).padStart(2, '0');
const length = sec >= 3600 ? `${Math.floor(sec / 3600)}:${pad(Math.floor(sec / 60) % 60)}:${pad(sec % 60)}` : `${Math.floor(sec / 60)}:${pad(sec % 60)}`;
// Đi qua nhánh ảnh bìa thì kết quả của nó nằm ở đây; lỗi có trường error.
const last = $input.first().json;
const why = String(last.error?.message ?? last.error ?? '');
const cover = !r.cover_file_id ? null
  : !last.error ? '🖼 Đã đặt ảnh bìa'
  : `⚠️ Chưa đặt được ảnh bìa: ${esc(why.slice(0, 300))}` +
    (/forbidden|permission|403/i.test(why) ? '\nKênh cần xác minh số điện thoại tại youtube.com/verify mới được đặt ảnh bìa riêng.' : '');
// YouTube có thể để video ở chế độ khác chế độ đã chọn (theo cài đặt của kênh): báo để mở YouTube Studio xem.
const privacy = video.status?.privacyStatus;
const wanted = cfg.privacy_status;
// TikTok của truyện chỉ gửi khi bấm Bắt đầu: truyện còn TikTok chưa bắt đầu thì nhắc kèm nút (trang quản lý xử lý).
const flags = {};
for (const f of $('Đọc cài đặt').all().map((i) => i.json)) if (f.key) flags[f.key] = String(f.value ?? '');
const tiktok = $('Đọc Sheet').all().map((i) => i.json).filter((x) => x.job_id === r.job_id && (x.format === 'tiktok' || x.format === 'original'));
const flag = flags[`tiktok:${r.job_id}`];
const started = flag === 'on' || (flag !== 'off' && tiktok.some((x) => ['inbox', 'posted', 'posting', 'skipped'].includes(x.status)));
const askTikTok = !started && tiktok.some((x) => x.status === 'pending');
const text = [
  '✅ <b>Đã đăng YouTube</b>',
  `🎬 ${esc(p.title)}`,
  `⏱ ${length}`,
  `🔗 https://youtu.be/${id}`,
  cover,
  privacy && wanted && privacy !== wanted ? `⚠️ YouTube đang để video ở chế độ ${esc(privacy)} (đã chọn ${esc(wanted)}), mở YouTube Studio để xem.` : null,
  askTikTok ? `\n🎵 TikTok của truyện này ${flag === 'off' ? 'đang dừng' : 'chưa bắt đầu'}: bấm nút bên dưới khi muốn đăng TikTok.` : null,
].filter(Boolean).join('\n');
return [{ json: { payload: {
  chat_id: cfg.telegram_chat_id, parse_mode: 'HTML', text,
  reply_markup: { inline_keyboard: [
    [{ text: '🔗 Mở video', url: `https://youtu.be/${id}` }],
    ...(askTikTok ? [[{ text: flag === 'off' ? '▶️ Chạy tiếp TikTok' : '🎵 Bắt đầu TikTok', callback_data: `st|ttstart|${r.job_id}` }]] : []),
  ] },
} } }];

const cfg = $('Cấu hình YouTube').first().json;
// Chưa điền bot Telegram thì bỏ qua bước nhắn tin.
if (!cfg.telegram_bot_token || cfg.telegram_bot_token.startsWith('DAN_')) return [];
const r = $('Lấy 1 video').first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const msg = String($input.first().json.note ?? '').slice(0, 1000);
const text = [
  '❌ <b>Không đăng được video lên YouTube</b>',
  `🎬 ${esc(r.post_title || r.title)}`,
  '',
  `<pre>${esc(msg || 'Lỗi không rõ, xem cột note trong Sheet')}</pre>`,
  'Sửa xong bấm 🔁 Đăng lại: video quay về hàng chờ, đăng ở lượt kế tiếp.',
].join('\n');
// Nút do trang quản lý Telegram xử lý.
return [{ json: { payload: { chat_id: cfg.telegram_chat_id, parse_mode: 'HTML', text, reply_markup: { inline_keyboard: [[
  { text: '🔁 Đăng lại', callback_data: `msg|retry|${r.id}` },
  { text: '⏭ Bỏ qua', callback_data: `msg|skip|${r.id}` },
]] } } } }];
